import type { Book } from "@/types";

import goodreadsLibrary from "@/data/goodreads-library.json";


/* =========================================================
   GOODREADS LIBRARY DATA
   ========================================================= */

type GoodreadsLibraryRecord = {
  book: Book;
};

const library =
  goodreadsLibrary as GoodreadsLibraryRecord[];

const books =
  library.map(
    (record) => record.book
  );


/* =========================================================
   SLAYBASE STATUS FILTERS
   ========================================================= */

const statusFilters = [
  {
    label: "All Books",
    count: 2507,
    accent: "pink",
  },
  {
    label: "TBR",
    count: 2115,
    accent: "violet",
  },
  {
    label: "Read",
    count: 384,
    accent: "ice",
  },
  {
    label: "Current",
    count: 4,
    accent: "mixed",
  },
  {
    label: "DNF",
    count: 4,
    accent: "pink",
  },
];


/* =========================================================
   DEVELOPMENT PREVIEW

   We only render the first 12 books for now.
   Search, filtering, sorting, and pagination come next.
   ========================================================= */

const previewBooks =
  books.slice(0, 12);

const bookAccents = [
  "pink",
  "violet",
  "ice",
  "mixed",
];


/* =========================================================
   SLAYBASE PAGE
   ========================================================= */

export default function SlaybasePage() {
  return (
    <main className="slaybase-page">

      {/* =========================
          SLAYBASE HERO
          ========================= */}

      <section className="slaybase-hero">
        <div>
          <p className="eyebrow">
            LIBRARY DATABASE // 2,507 RECORDS
          </p>

          <h1 className="slaybase-title">
            THE
            <span> SLAYBASE</span>
          </h1>

          <p className="slaybase-intro">
            Every book. Every shelf. Every questionable
            decision that somehow became part of the collection.
          </p>
        </div>

        <div className="slaybase-orbit">
          <span>2,507</span>
          <small>BOOKS INDEXED</small>
        </div>
      </section>


      {/* =========================
          STATUS FILTERS
          ========================= */}

      <section className="slaybase-status-grid">
        {statusFilters.map((filter) => (
          <button
            type="button"
            key={filter.label}
            className={`slaybase-status-card status-${filter.accent}`}
          >
            <span>
              {filter.label}
            </span>

            <strong>
              {filter.count.toLocaleString()}
            </strong>
          </button>
        ))}
      </section>


      {/* =========================
          CONTROL BAR
          ========================= */}

      <section className="slaybase-controls">

        <div className="slaybase-search">
          <span>⌕</span>

          <input
            type="search"
            placeholder="Search title, author, series..."
            aria-label="Search the Slaybase"
          />
        </div>

        <div className="slaybase-control-buttons">
          <button type="button">
            FILTERS +
          </button>

          <button type="button">
            SORT: RECENTLY ADDED
          </button>

          <button
            type="button"
            aria-label="Grid view"
          >
            ▦
          </button>

          <button
            type="button"
            aria-label="List view"
          >
            ☰
          </button>
        </div>

      </section>


      {/* =========================
          LIBRARY HEADING
          ========================= */}

      <section className="slaybase-library-heading">
        <div>
          <p className="eyebrow">
            CURRENT QUERY // ALL BOOKS
          </p>

          <h2 className="section-title">
            The Library
          </h2>
        </div>

        <p className="slaybase-results">
          SHOWING 12 OF 2,507
        </p>
      </section>


      {/* =========================
          REAL BOOK GRID
          ========================= */}

      <section className="slaybase-book-grid">

        {previewBooks.map(
          (book, index) => {
            const accent =
              bookAccents[
                index % bookAccents.length
              ];

            return (
              <article
                key={book.id}
                className="slaybase-book"
              >

                {/* BOOK COVER */}

                <div
                  className={`slaybase-book-cover book-${accent}`}
                >
                  <span className="book-status">
                    {book.status
                      .replaceAll("-", " ")
                      .toUpperCase()}
                  </span>

                  <span className="book-cover-symbol">
                    ✦
                  </span>

                  <strong>
                    {book.title}
                  </strong>
                </div>


                {/* BOOK INFORMATION */}

                <div className="slaybase-book-info">

                  <div className="book-info-heading">
                    <div>
                      <h3>
                        {book.title}
                      </h3>

                      <p>
                        {book.authors.join(", ")}
                      </p>
                    </div>

                    <button
                      type="button"
                      aria-label={`More options for ${book.title}`}
                    >
                      •••
                    </button>
                  </div>


                  {/* RATING */}

                  {book.personalRating ? (
                    <div className="book-rating">
                      {"★".repeat(
                        book.personalRating
                      )}

                      {"☆".repeat(
                        5 -
                          book.personalRating
                      )}
                    </div>
                  ) : (
                    <div className="book-rating unrated">
                      NOT YET RATED
                    </div>
                  )}


                  {/* SLAYLIST BADGES */}

                  <div className="book-tags">

                    {book.certifiedSlay && (
                      <span>
                        CERTIFIED SLAY
                      </span>
                    )}

                    {book.brainChemistry && (
                      <span>
                        BRAIN CHEMISTRY
                      </span>
                    )}

                    {book.primaryFormat && (
                      <span>
                        {book.primaryFormat.toUpperCase()}
                      </span>
                    )}

                  </div>

                </div>

              </article>
            );
          }
        )}

      </section>


      {/* =========================
          LOAD MORE
          ========================= */}

      <div className="slaybase-load-more">
        <button type="button">
          LOAD MORE FROM THE ARCHIVES ↓
        </button>

        <p>
          2,495 more books are minding their business
          in the database.
        </p>
      </div>

    </main>
  );
}
